const panel=document.getElementById('panel'),badge=document.getElementById('badge'),chapter=document.getElementById('chapter'),play=document.getElementById('play');
function renderPanel(){if(state.mode==='create'){panel.innerHTML=`<div class="eyebrow">Before the case begins</div><h1>Meet your detective.</h1><p class="intro">The Royal Night Mail is bound for Black Hollow. Somewhere aboard, a passenger has disappeared. First, let’s get you ready for the journey.</p><div class="section-title">Your name</div><div class="name-row"><input id="heroName" maxlength="16" placeholder="e.g. Alex Ashford" value="${esc(state.name)}" aria-label="Detective name"></div><div class="section-title">Character <span>01 — 02</span></div><div class="choices">${opts('gender')}</div><div class="section-title">Hairstyle</div><div class="choices">${opts('hair')}</div><div class="section-title">Complexion</div><div class="choices">${opts('skin')}</div><div class="section-title">Victorian attire</div><div class="choices">${opts('clothes')}</div><div class="rule"></div><div class="section-title">Choose your companion</div><div class="choices">${opts('pet')}</div><div class="name-row"><input id="petName" maxlength="14" placeholder="Name your ${optionData.pet[state.pet].toLowerCase()}" value="${esc(state.petName)}" aria-label="Pet name"></div><div class="mini-note">Your loyal companion will join you as you investigate all three carriages.</div>`;
play.innerHTML='▶ &nbsp; Board the train';play.style.display='block';document.getElementById('heroName').addEventListener('input',e=>state.name=e.target.value);document.getElementById('petName').addEventListener('input',e=>state.petName=e.target.value);document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{state[b.dataset.group]=Number(b.dataset.value);renderPanel()});badge.innerHTML='NO. 07 &nbsp;·&nbsp; <span>THE ROYAL NIGHT MAIL</span>';chapter.textContent='A DETECTIVE STORY · 1891';}
else{const c=carriages[state.car],found=state.clues.length,done=found===3;panel.innerHTML=`<div class="eyebrow">${done?'Case concluded':'The mystery begins'}</div><h1>${done?'A name in the night.':c.name.replace('THE ','')}</h1><p class="intro">${done?'Three clues. One vanished passenger. And a culprit who never left the train.':c.sub+'. A passenger has vanished between stations. Ask questions, inspect the carriage, and piece together the truth.'}</p><div class="rule"></div><div class="section-title">Passenger of interest</div><div style="font:600 17px 'Playfair Display',serif;color:#3b2930;margin:6px 0 3px">${c.npc}</div><div class="mini-note">${c.role}</div><button class="choice" id="talk" style="margin:13px 0 14px;width:100%;padding:10px">◈ &nbsp; Speak with ${c.npc}</button><div class="section-title">Evidence collected <span>${found} / 3</span></div><div class="choices">${carriages.map((cc,i)=>`<button class="choice ${state.clues.includes(i)?'active':''}" data-evidence="${i}" style="flex:1;text-align:center">${state.clues.includes(i)?'✦ '+cc.clue:'? '+['Telegram','Brass key','Watch'][i]}</button>`).join('')}</div><div class="rule"></div><div class="section-title">Your companion</div><div style="font:600 15px 'Playfair Display',serif;color:#3b2930;margin:5px 0 3px">${esc(state.petName)||'Your companion'} <span style="font:9px 'DM Mono';color:#8b7964">· ${optionData.pet[state.pet]}</span></div><p class="mini-note">${done?'The clues point to the one person who could have arranged it all.':'Explore the other carriages with the arrow buttons. Look closely—important things are easy to miss.'}</p>${done?'<button class="choice" id="solve" style="width:100%;padding:11px;background:#653641;color:#f5e1bd">✦ &nbsp; Unmask the culprit</button>':''}`;
play.innerHTML=done?'✦ &nbsp; Solve the mystery':'↗ &nbsp; Explore carriage';play.style.display='block';badge.innerHTML=`NO. 0${state.car+7} &nbsp;·&nbsp; <span>${c.name}</span>`;chapter.textContent=`CHAPTER I · ${found} / 3 CLUES`;document.getElementById('talk').onclick=()=>talk();document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.evidence);if(state.clues.includes(i))say('Evidence log',`Collected: ${carriages[i].clue}. The details are recorded in your case notes.`);else{state.car=i;renderPanel();inspectClue()}});let solve=document.getElementById('solve');if(solve)solve.onclick=()=>finish();}
}
function opts(group){return optionData[group].map((v,i)=>`<button class="choice ${state[group]===i?'active':''}" data-group="${group}" data-value="${i}">${v}</button>`).join('')}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function say(who,words){document.getElementById('speaker').textContent=who.toUpperCase();document.getElementById('line').textContent=words;document.getElementById('dialogue').classList.add('show')}
function hideDialogue(){document.getElementById('dialogue').classList.remove('show')}
function talk(){if(state.mode==='create')return;let progress=state.progress?.[state.car]||0,c=carriages[state.car];if(!state.progress)state.progress=[0,0,0];if(progress>=c.story.length){say(c.npc,'I’ve told you all I know, detective. Have you searched the other carriages?');return}say(c.npc,c.story[progress]);state.progress[state.car]++;if(state.progress[state.car]===c.story.length){state.met[state.car]=true;setTimeout(()=>{if(state.dialogueIndex===0){/* clue remains for inspection */}},0)}}
function inspectClue(){if(state.mode==='create')return;let words=['The telegram is torn cleanly in two. The remaining line reads: “…meet me in cabin six. 11:32. —V.”','A small brass luggage key, still warm. Its tag reads “CABIN 6”. Someone tried to hide it under the table.','A silver watch, stopped at 11:32. The engraved initials on the back: “E.V.”'];let c=state.car;if(state.clues.includes(c)){say('Case notes',`You have already secured the ${carriages[c].clue}. Its detail may matter later.`);return}state.clues.push(c);say('Evidence found',words[c]);renderPanel();showToast('CLUE ADDED TO YOUR CASE NOTES');}
function showToast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function finish(){state.ending=true;document.getElementById('dialogue').classList.remove('show');state.mode='ending';renderPanel();say('Case closed',`“E.V.” — Edward Vale, the physician. The three clues place him in cabin six at 11:32, staging a disappearance to flee his debts. Dr. Vale is escorted off at Black Hollow. Well done, ${state.name||'Detective'}.`);play.innerHTML='↻ &nbsp; Play again';play.onclick=()=>location.reload();}
function startGame(){state.mode='play';state.car=0;renderPanel();document.getElementById('status').textContent='THE ROYAL NIGHT MAIL · LONDON TO BLACK HOLLOW';say('The conductor',`Tickets, please! ${state.name||'Detective'}, your cabin is this way. Keep your ${state.petName||'companion'} close tonight… there’s a mystery aboard.`)}
function setCar(d){if(state.mode==='create')return;state.car=(state.car+d+3)%3;hideDialogue();renderPanel();document.getElementById('status').textContent=`THE ROYAL NIGHT MAIL · ${['11:47 PM','11:53 PM','12:02 AM'][state.car]} · ${['OBSERVATION SALOON','DINING CAR','SLEEPING CAR'][state.car]}`;state.walk+=d}

