function setCar(d){if(state.mode==='create'){state.pet=(state.pet+d+3)%3;renderPanel();return}if(state.mode==='ending')return;state.car=(state.car+d+3)%3;hideDialogue();renderPanel();document.getElementById('status').textContent=`THE ROYAL NIGHT MAIL · ${['11:47 PM','11:53 PM','12:02 AM'][state.car]} · ${['OBSERVATION SALOON','DINING CAR','SLEEPING CAR'][state.car]}`;state.walk+=d}
document.getElementById('prev').onclick=()=>setCar(-1);document.getElementById('next').onclick=()=>setCar(1);
play.onclick=()=>{if(state.mode==='create')startGame();else if(state.mode==='ending')location.reload();else if(state.clues.length===3)finish();else setCar(1)};
document.getElementById('dialogue').onclick=hideDialogue;
canvas.addEventListener('click',e=>{if(state.mode==='create')return;let b=canvas.getBoundingClientRect(),x=(e.clientX-b.left)/b.width*640,y=(e.clientY-b.top)/b.height*360;if(x>435&&x<520&&y>115&&y<245)talk();else if((state.car===0&&x>153&&x<212&&y>210)||(state.car===1&&x>505&&x<560&&y>195)||(state.car===2&&x>52&&x<111&&y>210))inspectClue();});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();setCar(-1)}else if(e.key==='ArrowRight'){e.preventDefault();setCar(1)}else if(e.key.toLowerCase()==='e'){inspectClue()}else if(e.key===' '){e.preventDefault();hideDialogue()}});
renderPanel();draw();
